// L leg -- SCR-118 / SCR-119 / SCR-120, the CHECKMULTISIG tail.
//
// REVIEWED TRANSLITERATION of the pass after cmsLoop in
// Bitcoin.Interpreter.Defs.checkMultiSig
// (spec/core/Bitcoin/Interpreter/Defs.lean:1091-1127), NOT generated by
// twin/gen.py:
//
//   checkMultiSig ctx w st :=
//     ...
//     | .ok fSuccess =>
//       match cmsCleanup ctx.pol st.stack fSuccess
//               (nKeys + nSigs + 3) (nKeys + 2) (nKeys + nSigs + 3) with
//       | .ok st₃ =>
//         if st₃.length < 1 then .error .stackUnderflow
//         else if ctx.flags.nullDummy ∧ st₃[0]!.size ≠ 0 then .error .sigNullDummy
//         else let st₄ := { st with opCount := opCount₂,
//                           stack := pushBoolV fSuccess :: st₃.tail }
//              if w = 0xaf then
//                if fSuccess then .ok { st₄ with stack := st₄.stack.tail }
//                else .error .checkMultiSigVerify
//              else .ok st₄
//
//   cmsCleanup pol st fSuccess i ikey2 fuel :=        -- Defs.lean:702-718
//     if i ≤ 1 then .ok st
//     else if !fSuccess ∧ pol.nullFail ∧ ikey2 = 0 ∧ st[0]!.size ≠ 0
//              then .error .sigNullFail
//     else cmsCleanup pol st.tail fSuccess (i-1) (if 0 < ikey2 then ikey2-1 else ikey2) f
//
// `cmsCleanup` consumes i-1 elements (tail recursion on `st.tail`); the slice
// computes the resulting depth arithmetically, which is the same function.  The
// NULLFAIL arm is disabled by this cell's domain (`pol.nullFail = false`), so
// cleanup only pops.  `pushBoolV true = vchTrue = {1}`, `pushBoolV false =
// vchFalse = {}` (Defs.lean:305-310); `st₃[0]!.size` is the *only* use of the
// extra item's content, which is the SCR-119 gate.
#include <cstdint>
#include "cms_obs.h"

extern "C" uint64_t cell_cms_tail(uint32_t nkeys, uint32_t nsigs,
                                  uint32_t extra, uint32_t fsuccess,
                                  uint32_t nulldummy, uint32_t wire,
                                  uint32_t dummyLen, uint32_t dummyBytes) {
  (void)dummyBytes;  // only st₃[0]!.size enters the rule

  // cmsCleanup is called with i = nKeys + nSigs + 3 and pops i-1 elements.
  const uint64_t pops = (uint64_t)nkeys + (uint64_t)nsigs + 2u;
  const uint64_t depth0 = (uint64_t)extra + pops + 1u;   // ... + the dummy
  const uint64_t depth1 = depth0 - pops;                 // dummy on top

  if (depth1 < 1u) return cms_fail_tail(CMS_INVALID_STACK_OPERATION);
  if (nulldummy != 0u && dummyLen != 0u) return cms_fail_tail(CMS_SIG_NULLDUMMY);

  const uint64_t remain = depth1 - 1u;   // st₃.tail: the dummy is dropped
  if (wire == 0xafu) {
    if (fsuccess == 0u) return cms_fail_tail(CMS_CHECKMULTISIGVERIFY);
    // pushBoolV then the VERIFY arm's tail: net depth = remain.
    return cms_pack_tail(1u, CMS_OK, (uint32_t)remain, 2u);
  }
  if (fsuccess != 0u) return cms_pack_tail(1u, CMS_OK, (uint32_t)remain, 1u);
  return cms_pack_tail(0u, CMS_EVAL_FALSE, (uint32_t)remain, 0u);
}
